import { spawn } from "node:child_process";

const executable = "@@ecco@@";
const baseArgs = ["traces","push","--from","opencode","--api","@@api@@","--home","@@home@@"];

function upload(args, input) {
  return new Promise((resolve) => {
    let child;
    let timer;
    const finish = () => { if (timer) clearTimeout(timer); resolve(); };
    try {
      child = spawn(executable, [...baseArgs, ...args], { stdio: [input === undefined ? "ignore" : "pipe", "ignore", "ignore"] });
      child.once("error", finish);
      child.once("exit", finish);
      if (input !== undefined) child.stdin.end(JSON.stringify(input));
      timer = setTimeout(() => { child.kill(); finish(); }, 60000);
      timer.unref?.();
    } catch {
      finish();
    }
  });
}

const active = new Set();

export const EccoTracePlugin = async () => ({
  event: async ({ event }) => {
    if (event?.type !== "session.idle") return;
    const sessionID = event?.properties?.sessionID;
    if (typeof sessionID !== "string" || !sessionID || active.has(sessionID)) return;
    active.add(sessionID);
    try {
      await upload([], { session_id: sessionID });
    } finally {
      active.delete(sessionID);
    }
  },
});

