import json
import subprocess

EXECUTABLE = "@@ecco@@"
BASE_ARGS = ["traces","push","--from","hermes","--api","@@api@@","--home","@@home@@"]

def _session_id(args, kwargs):
    value = kwargs.get("session_id")
    if isinstance(value, str):
        return value
    for item in args:
        if isinstance(item, dict) and isinstance(item.get("session_id"), str):
            return item["session_id"]
        if isinstance(item, str):
            return item
    return None

def _upload(*args, **kwargs):
    session_id = _session_id(args, kwargs)
    if not session_id:
        return
    try:
        subprocess.run(
            [EXECUTABLE, *BASE_ARGS],
            input=json.dumps({"session_id": session_id}),
            text=True,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            timeout=60,
            check=False,
        )
    except Exception:
        pass

def register(ctx):
    ctx.register_hook("on_session_end", _upload)
